WHERE USER_ID = #{userId}

mapper.select:
SELECT

    /* 총 데일리 기록 수 */
    (
        SELECT COUNT(*)
        FROM DAILY_REVIEWS
        WHERE USER_ID = #{userId}
    ) AS DAILY_REVIEW_COUNT,


    /* 평균 하루 평점 */
    (
        SELECT NVL(
            ROUND(
                AVG(TOTAL_RATING),
                1
            ),
            0
        )
        FROM DAILY_REVIEWS
        WHERE USER_ID = #{userId}
    ) AS AVERAGE_RATING,


    /* 총 서브 리뷰 수 */
    (
        SELECT COUNT(*)
        FROM SUB_REVIEWS SR
        JOIN DAILY_REVIEWS DR
          ON SR.REVIEW_ID = DR.REVIEW_ID
        WHERE DR.USER_ID = #{userId}
    ) AS SUB_REVIEW_COUNT,


    /* 내돈내산 인증률 */
    (
        SELECT
            NVL(
                ROUND(
                    SUM(
                        CASE
                            WHEN SR.IS_CERTIFIED = 'Y'
                            THEN 1
                            ELSE 0
                        END
                    )
                    / NULLIF(
                        COUNT(*),
                        0
                    )
                    * 100,
                    1
                ),
                0
            )
        FROM SUB_REVIEWS SR
        JOIN DAILY_REVIEWS DR
          ON SR.REVIEW_ID = DR.REVIEW_ID
        WHERE DR.USER_ID = #{userId}
    ) AS CERTIFICATION_RATE,


    /* 장소 카테고리 수 */
    (
        SELECT COUNT(*)
        FROM SUB_REVIEWS SR
        JOIN DAILY_REVIEWS DR
          ON SR.REVIEW_ID = DR.REVIEW_ID
        WHERE DR.USER_ID = #{userId}
          AND SR.CATEGORY = 'place'
    ) AS PLACE_COUNT,


    /* 아이템 카테고리 수 */
    (
        SELECT COUNT(*)
        FROM SUB_REVIEWS SR
        JOIN DAILY_REVIEWS DR
          ON SR.REVIEW_ID = DR.REVIEW_ID
        WHERE DR.USER_ID = #{userId}
          AND SR.CATEGORY = 'item'
    ) AS ITEM_COUNT,


    /* 이동수단 카테고리 수 */
    (
        SELECT COUNT(*)
        FROM SUB_REVIEWS SR
        JOIN DAILY_REVIEWS DR
          ON SR.REVIEW_ID = DR.REVIEW_ID
        WHERE DR.USER_ID = #{userId}
          AND SR.CATEGORY = 'transport'
    ) AS TRANSPORT_COUNT,


    /* 콘텐츠 카테고리 수 */
    (
        SELECT COUNT(*)
        FROM SUB_REVIEWS SR
        JOIN DAILY_REVIEWS DR
          ON SR.REVIEW_ID = DR.REVIEW_ID
        WHERE DR.USER_ID = #{userId}
          AND SR.CATEGORY = 'content'
    ) AS CONTENT_COUNT

FROM DUAL
